class Resource {
    int* data;
public:
    // Copy Constructor (Lvalue)
    Resource(const Resource& other);

    // Move Constructor (Rvalue, enables resource transfer)
    Resource(Resource&& other) noexcept {
        data = other.data;
        other.data = nullptr; // Nullify source
    }
};

void process(int& l) {}   // Lvalue reference
void process(int&& r) {}  // Rvalue reference

int x = 5;
process(x);             // Calls process(int& l)
process(10);            // Calls process(int&& r)

// std::move converts lvalue x into an rvalue expression
process(std::move(x));  // Calls process(int&& r)
